import heapq, math

def astar(grid, start, goal):
    # grid is 1 where a rock is; cells are (row, col)
    h = lambda c: math.hypot(c[0] - goal[0], c[1] - goal[1])
    queue, came, cost = [(h(start), start)], {}, {start: 0}
    while queue:
        _, cell = heapq.heappop(queue)
        if cell == goal:
            path = [cell]
            while cell in came:
                cell = came[cell]
                path.append(cell)
            return path[::-1]
        for dr, dc in [(a, b) for a in (-1, 0, 1) for b in (-1, 0, 1) if a or b]:
            r, c = cell[0] + dr, cell[1] + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and not grid[r][c]:
                new = cost[cell] + math.hypot(dr, dc)
                if new < cost.get((r, c), 1e9):
                    cost[(r, c)], came[(r, c)] = new, cell
                    heapq.heappush(queue, (new + h((r, c)), (r, c)))

def to_cell(x, y):
    return (int(y) // CELL, int(x) // CELL)       # pixels -> (row, column)

def plan(frame, rover_id=7, goal_id=3):
    seen = find_markers(frame)
    if rover_id not in seen or goal_id not in seen:
        return None, seen                         # a marker is hidden: no plan
    grid = make_grid(frame)
    start = to_cell(*seen[rover_id][:2])
    goal = to_cell(*seen[goal_id][:2])
    for r, c in (start, goal):                    # black marker squares are not rocks
        grid[max(r - 3, 0):r + 4, max(c - 3, 0):c + 4] = 0
    return astar(grid.tolist(), start, goal), seen

def steer(seen, path, rover_id=7, ahead=3):
    """Return (left, right) motor speeds from -255 to 255."""
    x, y, heading = seen[rover_id]
    row, col = path[min(ahead, len(path) - 1)]    # aim a few cells ahead
    tx, ty = col * CELL + CELL / 2, row * CELL + CELL / 2
    want = math.degrees(math.atan2(ty - y, tx - x))
    error = (want - heading + 180) % 360 - 180    # -180 to 180
    if abs(error) > 30:                           # wrong way round: spin
        return (150, -150) if error > 0 else (-150, 150)
    return 200 + int(error * 2), 200 - int(error * 2)

