void loop() {
  char text[32];
  if (udp.parsePacket() > 0) {
    int len = udp.read(text, sizeof(text) - 1);
    text[len] = 0;
    int left, right;
    if (sscanf(text, "%d,%d", &left, &right) == 2) {   // text like "200,-200"
      drive(left, right);
      lastPacket = millis();
    }
  }
  if (millis() - lastPacket > 500) drive(0, 0);    // laptop went quiet: stop
